}

///  Digital Terrain Tile
///
///  One addressable tile of a terrain elevation pyramid: its address in a
///  stated tiling scheme, its geographic extent, its payload encoding and where
///  those bytes live, the vertical datum its heights are measured from, what it
///  states about water cover, and the dataset edition and licence it was
///  redistributed under.
///
///  $DTT is the SERVED ARTIFACT of a terrain lane and is deliberately not
///  $TRN, which configures how a consumer uses terrain (sources, interpolation,
///  cache size, exaggeration) and holds no elevation; nor $TRS, which is a
///  radio-propagation solve over terrain heights. A terrain service publishes
///  $DTT records, is configured by $TRN, and its heights may be consumed by
///  $TRS.
///
///  Angles are decimal degrees on WGS 84 and heights are metres. Tile bytes are
///  referenced by content identifier by default; see DTTPayloadRef.
public struct DTT: FlatBufferTable, FlatbuffersVectorInitializable, Verifiable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$DTT" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: DTT.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let TILESET_ID: VOffset = 4
    static let TILESET_NAME: VOffset = 6
    static let TILING_SCHEME: VOffset = 8
    static let LEVEL: VOffset = 10
    static let X: VOffset = 12
    static let Y: VOffset = 14
    static let ROW_ORIGIN_NORTH: VOffset = 16
    static let WEST_DEG: VOffset = 18
    static let SOUTH_DEG: VOffset = 20
    static let EAST_DEG: VOffset = 22
    static let NORTH_DEG: VOffset = 24
    static let MIN_HEIGHT_M: VOffset = 26
    static let MAX_HEIGHT_M: VOffset = 28
    static let PAYLOAD_FORMAT: VOffset = 30
    static let PAYLOAD_FORMAT_VERSION: VOffset = 32
    static let PAYLOAD: VOffset = 34
    static let GRID_WIDTH: VOffset = 36
    static let GRID_HEIGHT: VOffset = 38
    static let POST_SPACING_M: VOffset = 40
    static let SOURCE_POST_SPACING_M: VOffset = 42
    static let VERTICAL_DATUM: VOffset = 44
    static let VERTICAL_DATUM_NAME: VOffset = 46
    static let HORIZONTAL_DATUM_NAME: VOffset = 48
    static let VERTICAL_ACCURACY_M: VOffset = 50
    static let ACCURACY_CONFIDENCE: VOffset = 52
    static let HORIZONTAL_ACCURACY_M: VOffset = 54
    static let DATA_COVERAGE_FRACTION: VOffset = 56
    static let NO_DATA_VALUE: VOffset = 58
    static let WATER_MASK_KIND: VOffset = 60
    static let WATER_MASK: VOffset = 62
    static let WATER_MASK_WIDTH: VOffset = 64
    static let WATER_MASK_HEIGHT: VOffset = 66
    static let WATER_MASK_PROVENANCE: VOffset = 68
    static let VERTEX_NORMALS: VOffset = 70
    static let LAND_COVER: VOffset = 72
    static let CHILD_AVAILABILITY: VOffset = 74
    static let MAX_LEVEL: VOffset = 76
    static let SOURCE_CLASS: VOffset = 78
    static let PROVENANCE: VOffset = 80
    static let EPOCH: VOffset = 82
    static let ETAG: VOffset = 84
    static let EXPIRES: VOffset = 86
    static let REMARKS: VOffset = 88
  }

  ///  Publisher-stable identifier for the tile pyramid (the tileset) this tile
  ///  belongs to. Tiles of one pyramid share a scheme, format, and datum.
  public var TILESET_ID: String! { let o = _accessor.offset(VT.TILESET_ID); return _accessor.string(at: o) }
  public var TILESET_IDSegmentArray: [UInt8]! { return _accessor.getVector(at: VT.TILESET_ID) }
  ///  The tileset's own name, verbatim, for display.
  public var TILESET_NAME: String? { let o = _accessor.offset(VT.TILESET_NAME); return o == 0 ? nil : _accessor.string(at: o) }
  public var TILESET_NAMESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.TILESET_NAME) }
  ///  Scheme the address below is expressed in.
  public var TILING_SCHEME: dttTilingScheme { let o = _accessor.offset(VT.TILING_SCHEME); return o == 0 ? .unspecified : dttTilingScheme(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unspecified }
  ///  Zoom level of the tile, 0 at the pyramid root.
  public var LEVEL: UInt32 { let o = _accessor.offset(VT.LEVEL); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Column index within LEVEL, increasing eastward from the scheme origin.
  public var X: UInt32 { let o = _accessor.offset(VT.X); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Row index within LEVEL, increasing in the scheme's own row direction;
  ///  ROW_ORIGIN_NORTH states which.
  public var Y: UInt32 { let o = _accessor.offset(VT.Y); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Row index 0 lies at the north edge of the scheme. When false, row 0 lies
  ///  at the south edge.
  public var ROW_ORIGIN_NORTH: Bool { let o = _accessor.offset(VT.ROW_ORIGIN_NORTH); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Western extent of the tile, decimal degrees on WGS 84.
  public var WEST_DEG: Double { let o = _accessor.offset(VT.WEST_DEG); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Southern extent of the tile, decimal degrees on WGS 84.
  public var SOUTH_DEG: Double { let o = _accessor.offset(VT.SOUTH_DEG); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Eastern extent of the tile, decimal degrees on WGS 84.
  public var EAST_DEG: Double { let o = _accessor.offset(VT.EAST_DEG); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Northern extent of the tile, decimal degrees on WGS 84.
  public var NORTH_DEG: Double { let o = _accessor.offset(VT.NORTH_DEG); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Lowest height present in the tile, metres above VERTICAL_DATUM. Stated
  ///  so a consumer can build a bounding volume without decoding the payload.
  public var MIN_HEIGHT_M: Double { let o = _accessor.offset(VT.MIN_HEIGHT_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Highest height present in the tile, metres above VERTICAL_DATUM.
  public var MAX_HEIGHT_M: Double { let o = _accessor.offset(VT.MAX_HEIGHT_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Encoding of the payload bytes.
  public var PAYLOAD_FORMAT: dttPayloadFormat { let o = _accessor.offset(VT.PAYLOAD_FORMAT); return o == 0 ? .unspecified : dttPayloadFormat(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unspecified }
  ///  Version of PAYLOAD_FORMAT the bytes conform to, verbatim, when the
  ///  format is versioned.
  public var PAYLOAD_FORMAT_VERSION: String? { let o = _accessor.offset(VT.PAYLOAD_FORMAT_VERSION); return o == 0 ? nil : _accessor.string(at: o) }
  public var PAYLOAD_FORMAT_VERSIONSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PAYLOAD_FORMAT_VERSION) }
  ///  The tile's elevation bytes.
  public var PAYLOAD: DTTPayloadRef! { let o = _accessor.offset(VT.PAYLOAD); return DTTPayloadRef(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  Number of height posts across the tile for gridded formats. Unset for
  ///  mesh formats, whose vertex count varies.
  public var GRID_WIDTH: UInt32 { let o = _accessor.offset(VT.GRID_WIDTH); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Number of height posts down the tile for gridded formats.
  public var GRID_HEIGHT: UInt32 { let o = _accessor.offset(VT.GRID_HEIGHT); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Nominal ground distance between adjacent height posts at the tile
  ///  centre, metres. The tile's effective resolution as served, which is not
  ///  necessarily the source dataset's native post spacing.
  public var POST_SPACING_M: Double { let o = _accessor.offset(VT.POST_SPACING_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Native post spacing of the source elevations, metres, when the tile was
  ///  resampled from a coarser or finer grid.
  public var SOURCE_POST_SPACING_M: Double { let o = _accessor.offset(VT.SOURCE_POST_SPACING_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Surface the heights are measured from.
  public var VERTICAL_DATUM: dttVerticalDatum { let o = _accessor.offset(VT.VERTICAL_DATUM); return o == 0 ? .unspecified : dttVerticalDatum(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unspecified }
  ///  The datum, geoid model, or vertical reference frame named verbatim as
  ///  its authority states it.
  public var VERTICAL_DATUM_NAME: String? { let o = _accessor.offset(VT.VERTICAL_DATUM_NAME); return o == 0 ? nil : _accessor.string(at: o) }
  public var VERTICAL_DATUM_NAMESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.VERTICAL_DATUM_NAME) }
  ///  Horizontal reference frame the extent is expressed in, verbatim, when it
  ///  is not WGS 84.
  public var HORIZONTAL_DATUM_NAME: String? { let o = _accessor.offset(VT.HORIZONTAL_DATUM_NAME); return o == 0 ? nil : _accessor.string(at: o) }
  public var HORIZONTAL_DATUM_NAMESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.HORIZONTAL_DATUM_NAME) }
  ///  Vertical accuracy the publisher states for this tile, metres, at the
  ///  confidence level stated in ACCURACY_CONFIDENCE.
  public var VERTICAL_ACCURACY_M: Double { let o = _accessor.offset(VT.VERTICAL_ACCURACY_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Confidence level the accuracy figures are stated at, as a fraction
  ///  between 0 and 1.
  public var ACCURACY_CONFIDENCE: Double { let o = _accessor.offset(VT.ACCURACY_CONFIDENCE); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Horizontal accuracy the publisher states for this tile, metres.
  public var HORIZONTAL_ACCURACY_M: Double { let o = _accessor.offset(VT.HORIZONTAL_ACCURACY_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Fraction of the tile extent covered by real measurements rather than
  ///  interpolated or filled values, between 0 and 1.
  public var DATA_COVERAGE_FRACTION: Double { let o = _accessor.offset(VT.DATA_COVERAGE_FRACTION); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Height value used to mark absent samples in gridded payloads.
  public var NO_DATA_VALUE: Double { let o = _accessor.offset(VT.NO_DATA_VALUE); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  What the tile states about water cover.
  public var WATER_MASK_KIND: dttWaterMask { let o = _accessor.offset(VT.WATER_MASK_KIND); return o == 0 ? .none_ : dttWaterMask(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .none_ }
  ///  The per-sample water mask bytes when WATER_MASK_KIND is RASTER: one
  ///  unsigned byte per sample, 255 fully water, 0 fully land.
  public var WATER_MASK: DTTPayloadRef? { let o = _accessor.offset(VT.WATER_MASK); return o == 0 ? nil : DTTPayloadRef(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  Number of mask samples across and down the tile when WATER_MASK_KIND is
  ///  RASTER. Independent of GRID_WIDTH/GRID_HEIGHT: a mask is commonly
  ///  carried at a different resolution than the heights.
  public var WATER_MASK_WIDTH: UInt32 { let o = _accessor.offset(VT.WATER_MASK_WIDTH); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  public var WATER_MASK_HEIGHT: UInt32 { let o = _accessor.offset(VT.WATER_MASK_HEIGHT); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Dataset the water mask was derived from, when it is not the elevation
  ///  dataset. A separate lineage because a mask carries its own licence.
  public var WATER_MASK_PROVENANCE: DTTProvenance? { let o = _accessor.offset(VT.WATER_MASK_PROVENANCE); return o == 0 ? nil : DTTProvenance(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  Per-sample surface normals accompanying the tile, when the publisher
  ///  serves them, so a consumer need not derive lighting from heights.
  public var VERTEX_NORMALS: DTTPayloadRef? { let o = _accessor.offset(VT.VERTEX_NORMALS); return o == 0 ? nil : DTTPayloadRef(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  Per-sample land-cover classification accompanying the tile, when the
  ///  publisher serves one.
  public var LAND_COVER: DTTPayloadRef? { let o = _accessor.offset(VT.LAND_COVER); return o == 0 ? nil : DTTPayloadRef(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  Availability of the four child tiles at LEVEL+1, as the low four bits:
  ///  bit 0 south-west, bit 1 south-east, bit 2 north-west, bit 3 north-east.
  ///  A set bit states the child exists in this tileset.
  public var CHILD_AVAILABILITY: UInt8 { let o = _accessor.offset(VT.CHILD_AVAILABILITY); return o == 0 ? 0 : _accessor.readBuffer(of: UInt8.self, at: o) }
  ///  The deepest level this tileset serves anywhere. A consumer stops
  ///  requesting below it rather than discovering absence by failed fetches.
  public var MAX_LEVEL: UInt32 { let o = _accessor.offset(VT.MAX_LEVEL); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Production technique class of the source elevations.
  public var SOURCE_CLASS: dttSourceClass { let o = _accessor.offset(VT.SOURCE_CLASS); return o == 0 ? .unspecified : dttSourceClass(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unspecified }
  ///  Dataset lineage and redistribution terms. Required.
  public var PROVENANCE: DTTProvenance! { let o = _accessor.offset(VT.PROVENANCE); return DTTProvenance(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  RFC 3339 UTC fixed-millisecond epoch the elevations represent, when the
