  public var EPOCH: String? { let o = _accessor.offset(VT.EPOCH); return o == 0 ? nil : _accessor.string(at: o) }
  public var EPOCHSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.EPOCH) }
  ///  Entity tag for the served bytes, verbatim, so a cache can revalidate.
  public var ETAG: String? { let o = _accessor.offset(VT.ETAG); return o == 0 ? nil : _accessor.string(at: o) }
  public var ETAGSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.ETAG) }
  ///  RFC 3339 UTC timestamp after which this tile should be revalidated.
  public var EXPIRES: String? { let o = _accessor.offset(VT.EXPIRES); return o == 0 ? nil : _accessor.string(at: o) }
  public var EXPIRESSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.EXPIRES) }
  ///  Free-form publisher notes about this tile. Never a substitute for a
  ///  stated field.
  public var REMARKS: String? { let o = _accessor.offset(VT.REMARKS); return o == 0 ? nil : _accessor.string(at: o) }
  public var REMARKSSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.REMARKS) }
