    EXPIRESOffset EXPIRES: Offset = Offset(),
    REMARKSOffset REMARKS: Offset = Offset()
  ) -> Offset {
    let __start = DTT.startDTT(&fbb)
    DTT.add(TILESET_ID: TILESET_ID, &fbb)
