    DTT.add(PAYLOAD: PAYLOAD, &fbb)
    DTT.add(GRID_WIDTH: GRID_WIDTH, &fbb)
    DTT.add(GRID_HEIGHT: GRID_HEIGHT, &fbb)
    DTT.add(POST_SPACING_M: POST_SPACING_M, &fbb)
    DTT.add(SOURCE_POST_SPACING_M: SOURCE_POST_SPACING_M, &fbb)
    DTT.add(VERTICAL_DATUM: VERTICAL_DATUM, &fbb)
    DTT.add(VERTICAL_DATUM_NAME: VERTICAL_DATUM_NAME, &fbb)
    DTT.add(HORIZONTAL_DATUM_NAME: HORIZONTAL_DATUM_NAME, &fbb)
    DTT.add(VERTICAL_ACCURACY_M: VERTICAL_ACCURACY_M, &fbb)
    DTT.add(ACCURACY_CONFIDENCE: ACCURACY_CONFIDENCE, &fbb)
    DTT.add(HORIZONTAL_ACCURACY_M: HORIZONTAL_ACCURACY_M, &fbb)
    DTT.add(DATA_COVERAGE_FRACTION: DATA_COVERAGE_FRACTION, &fbb)
    DTT.add(NO_DATA_VALUE: NO_DATA_VALUE, &fbb)
    DTT.add(WATER_MASK_KIND: WATER_MASK_KIND, &fbb)
    DTT.add(WATER_MASK: WATER_MASK, &fbb)
    DTT.add(WATER_MASK_WIDTH: WATER_MASK_WIDTH, &fbb)
    DTT.add(WATER_MASK_HEIGHT: WATER_MASK_HEIGHT, &fbb)
    DTT.add(WATER_MASK_PROVENANCE: WATER_MASK_PROVENANCE, &fbb)
    DTT.add(VERTEX_NORMALS: VERTEX_NORMALS, &fbb)
    DTT.add(LAND_COVER: LAND_COVER, &fbb)
    DTT.add(CHILD_AVAILABILITY: CHILD_AVAILABILITY, &fbb)
    DTT.add(MAX_LEVEL: MAX_LEVEL, &fbb)
    DTT.add(SOURCE_CLASS: SOURCE_CLASS, &fbb)
    DTT.add(PROVENANCE: PROVENANCE, &fbb)
    DTT.add(EPOCH: EPOCH, &fbb)
    DTT.add(ETAG: ETAG, &fbb)
    DTT.add(EXPIRES: EXPIRES, &fbb)
    DTT.add(REMARKS: REMARKS, &fbb)
    return DTT.endDTT(&fbb, start: __start)
